fn solve(input: Vec<char>) -> Vec<char> {
    // Step 1: Remove a single trailing newline if present
    let mut s = input;
    if let Some(&'\n') = s.last() {
        s.pop();
    }

    // Helper to identify whitespace characters as defined by the problem
    fn is_ws(c: char) -> bool {
        matches!(c, ' ' | '\t' | '\n' | '\r')
    }

    // Step 2: Trim leading and trailing whitespace
    let mut start = 0;
    while start < s.len() && is_ws(s[start]) {
        start += 1;
    }
    let mut end = s.len();
    while end > start && is_ws(s[end - 1]) {
        end -= 1;
    }
    let s: Vec<char> = s[start..end].to_vec();

    // Step 3: Check password validity
    let is_long_enough = s.len() >= 5;
    let has_lower = s.iter().any(|&c| c.is_ascii_lowercase());
    let has_upper = s.iter().any(|&c| c.is_ascii_uppercase());
    let has_digit = s.iter().any(|&c| c.is_ascii_digit());

    let result = if is_long_enough && has_lower && has_upper && has_digit {
        "Correct\n"
    } else {
        "Too weak\n"
    };

    result.chars().collect()
}

